/* Graphite Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="graphite-light"] {
  --background: rgb(242, 242, 242);
  --foreground: rgb(51, 51, 51);
  --card: rgb(245, 245, 245);
  --card-foreground: rgb(51, 51, 51);
  --popover: rgb(245, 245, 245);
  --popover-foreground: rgb(51, 51, 51);
  --primary: rgb(96, 96, 96);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(225, 225, 225);
  --secondary-foreground: rgb(51, 51, 51);
  --muted: rgb(219, 219, 219);
  --muted-foreground: rgb(102, 102, 102);
  --accent: rgb(193, 193, 193);
  --accent-foreground: rgb(51, 51, 51);
  --destructive: rgb(204, 51, 51);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(209, 209, 209);
  --input: rgb(225, 225, 225);
  --ring: rgb(96, 96, 96);
  --chart-1: rgb(96, 96, 96);
  --chart-2: rgb(69, 104, 104);
  --chart-3: rgb(143, 143, 143);
  --chart-4: rgb(168, 168, 168);
  --chart-5: rgb(193, 193, 193);
  --radius: 0.35rem;
  --sidebar: rgb(235, 235, 235);
  --sidebar-foreground: rgb(51, 51, 51);
  --sidebar-primary: rgb(96, 96, 96);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(193, 193, 193);
  --sidebar-accent-foreground: rgb(51, 51, 51);
  --sidebar-border: rgb(209, 209, 209);
  --sidebar-ring: rgb(96, 96, 96);
  --font-sans: Montserrat, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: rgba(51, 51, 51, 0.1);
  --shadow-opacity: 0.15;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 0px 0px hsl(0 0% 20% / 0.07);
  --shadow-xs: 0px 2px 0px 0px hsl(0 0% 20% / 0.07);
  --shadow-sm:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 1px 2px -1px hsl(0 0% 20% / 0.15);
  --shadow:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 1px 2px -1px hsl(0 0% 20% / 0.15);
  --shadow-md:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 2px 4px -1px hsl(0 0% 20% / 0.15);
  --shadow-lg:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 4px 6px -1px hsl(0 0% 20% / 0.15);
  --shadow-xl:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 8px 10px -1px hsl(0 0% 20% / 0.15);
  --shadow-2xl: 0px 2px 0px 0px hsl(0 0% 20% / 0.38);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="graphite-dark"] {
  --background: rgb(27, 27, 27);
  --foreground: rgb(219, 219, 219);
  --card: rgb(31, 31, 31);
  --card-foreground: rgb(219, 219, 219);
  --popover: rgb(31, 31, 31);
  --popover-foreground: rgb(219, 219, 219);
  --primary: rgb(161, 161, 161);
  --primary-foreground: rgb(27, 27, 27);
  --secondary: rgb(48, 48, 48);
  --secondary-foreground: rgb(219, 219, 219);
  --muted: rgb(43, 43, 43);
  --muted-foreground: rgb(128, 128, 128);
  --accent: rgb(64, 64, 64);
  --accent-foreground: rgb(219, 219, 219);
  --destructive: rgb(223, 104, 103);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(53, 53, 53);
  --input: rgb(48, 48, 48);
  --ring: rgb(161, 161, 161);
  --chart-1: rgb(161, 161, 161);
  --chart-2: rgb(129, 155, 158);
  --chart-3: rgb(113, 113, 113);
  --chart-4: rgb(88, 88, 88);
  --chart-5: rgb(64, 64, 64);
  --radius: 0.35rem;
  --sidebar: rgb(31, 31, 31);
  --sidebar-foreground: rgb(219, 219, 219);
  --sidebar-primary: rgb(161, 161, 161);
  --sidebar-primary-foreground: rgb(27, 27, 27);
  --sidebar-accent: rgb(64, 64, 64);
  --sidebar-accent-foreground: rgb(219, 219, 219);
  --sidebar-border: rgb(53, 53, 53);
  --sidebar-ring: rgb(161, 161, 161);
  --font-sans: Inter, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: rgba(51, 51, 51, 0.1);
  --shadow-opacity: 0.15;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 0px 0px hsl(0 0% 20% / 0.07);
  --shadow-xs: 0px 2px 0px 0px hsl(0 0% 20% / 0.07);
  --shadow-sm:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 1px 2px -1px hsl(0 0% 20% / 0.15);
  --shadow:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 1px 2px -1px hsl(0 0% 20% / 0.15);
  --shadow-md:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 2px 4px -1px hsl(0 0% 20% / 0.15);
  --shadow-lg:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 4px 6px -1px hsl(0 0% 20% / 0.15);
  --shadow-xl:
    0px 2px 0px 0px hsl(0 0% 20% / 0.15), 0px 8px 10px -1px hsl(0 0% 20% / 0.15);
  --shadow-2xl: 0px 2px 0px 0px hsl(0 0% 20% / 0.38);
}
